export function annotateDecisionWeights(
  decision: unknown,
  evidence: unknown,
): DecisionWeightAnnotation | null {
  const valid = readDecision(decision);
  if (!valid) return null;
  const origin = readOrigin(valid, evidence);
  const selectedWeight = valid.status === "ok" ? valid.probabilities[valid.action] : null;
  return {
    schemaVersion: 1,
    origin,
    selectedWeight,
    reportedSelectedWeight: origin === "provider_reported" ? selectedWeight : null,
    financialCalibration: "not_established",
  };
}

test("historical unit weights retain their value without implying provider provenance", () => {
  const decision = Object.freeze({
    action: "buy",
    probabilities: Object.freeze({ buy: 1, sell: 0, hold: 0 }),
    status: "ok",
    confidence: 1,
    privateText: "must not escape",
  });
  const evidence = Object.freeze({ kind: "historical_record" });
  const before = JSON.stringify({ decision, evidence });

  expect(annotateDecisionWeights(decision, evidence)).toEqual({
    schemaVersion: 1,
    origin: "unknown",
    selectedWeight: 1,
    reportedSelectedWeight: null,
    financialCalibration: "not_established",
  });
  expect(JSON.stringify({ decision, evidence })).toBe(before);

test("repeated annotations of frozen provider evidence remain pure and exclude extra fields", () => {
  const decision = Object.freeze({
    action: "sell", status: "ok", probabilities: Object.freeze({ buy: 0.25, sell: 0.5, hold: 0.25 }),
    confidence: 0.5, model: "fixture-model", text: "fixture private text",
  });
  const evidence = Object.freeze({ kind: "observed_response", raw: Object.freeze({
    choice: "sell", probabilities: Object.freeze({ buy: 1, sell: 2, hold: 1 }),
    token: "synthetic-token", text: "untrusted instruction",
  }) });
  const before = JSON.stringify({ decision, evidence });
  const expected = {
    schemaVersion: 1, origin: "provider_reported", selectedWeight: 0.5,
    reportedSelectedWeight: 0.5, financialCalibration: "not_established",
  } as const;
  expect(annotateDecisionWeights(decision, evidence)).toEqual(expected);
  expect(annotateDecisionWeights(decision, evidence)).toEqual(expected);
  expect(JSON.stringify({ decision, evidence })).toBe(before);
  expect(Object.keys(annotateDecisionWeights(decision, evidence)!)).toEqual([
    "schemaVersion", "origin", "selectedWeight", "reportedSelectedWeight", "financialCalibration",
  ]);

function readResponse(value: unknown): { action: Action; probabilities: Weights; reported: boolean } | null {
  if (!isRecord(value) || !isAction(value.choice)) return null;
  if (value.probabilities === undefined) {
    return { action: value.choice, probabilities: {
      buy: value.choice === "buy" ? 1 : 0,
      sell: value.choice === "sell" ? 1 : 0,
      hold: value.choice === "hold" ? 1 : 0,
    }, reported: false };
  }
  if (!isRecord(value.probabilities)) return null;
  const buy = value.probabilities.buy ?? 0;
  const sell = value.probabilities.sell ?? 0;
  const hold = value.probabilities.hold ?? 0;
  if (![buy, sell, hold].every(weight => typeof weight === "number" && Number.isFinite(weight) && weight >= 0)) return null;
  const weights = { buy, sell, hold } as Weights;
  const total = weights.buy + weights.sell + weights.hold;
  if (!Number.isFinite(total) || total <= 0 || weights[value.choice] <= 0) return null;
  const normalized = { buy: weights.buy / total, sell: weights.sell / total, hold: weights.hold / total };
  if (!Object.values(normalized).every(Number.isFinite) || normalized[value.choice] <= 0) return null;
  return { action: value.choice, probabilities: normalized, reported: true };
}

function equalWeights(a: Weights, b: Weights): boolean {
  return Math.abs(a.buy - b.buy) <= TOLERANCE
    && Math.abs(a.sell - b.sell) <= TOLERANCE
    && Math.abs(a.hold - b.hold) <= TOLERANCE;

function readOrigin(decision: Decision, evidence: unknown): DecisionWeightAnnotation["origin"] {
  if (!isRecord(evidence)) return "unknown";
  const canonicalHold = decision.action === "hold" && decision.probabilities.buy === 0
    && decision.probabilities.sell === 0 && decision.probabilities.hold === 1;
  if (evidence.kind === "observed_failure") {
    return canonicalHold && (evidence.status === "error" || evidence.status === "timeout")
      && decision.status === evidence.status ? "adapter_safety_fallback" : "unknown";
  }
  if (evidence.kind !== "observed_response" || !("raw" in evidence)) return "unknown";
  const response = readResponse(evidence.raw);
  if (!response && canonicalHold && decision.status === "malformed") return "adapter_safety_fallback";
  if (response && decision.status === "ok" && response.action === decision.action
    && equalWeights(response.probabilities, decision.probabilities)) {
    return response.reported ? "provider_reported" : "adapter_choice_fallback";
  }
  return "unknown";

export function validateTapeDecision(raw: unknown, model: string): TapeDecision {
  const latency = isRecord(raw) && typeof raw.latencyMs === "number" && Number.isFinite(raw.latencyMs) && raw.latencyMs >= 0 ? raw.latencyMs : 0;
  if (!isRecord(raw) || !isAction(raw.choice)) return holdOnly(model, latency, "malformed");
  const action = raw.choice;

  let probabilities: Record<TapeAction, number>;
  if (raw.probabilities === undefined) {
    probabilities = { buy: 0, sell: 0, hold: 0, [action]: 1 } as Record<TapeAction, number>;
  } else {
    if (!isRecord(raw.probabilities)) return holdOnly(model, latency, "malformed");
    const weights = {} as Record<TapeAction, number>;
    let total = 0;
    for (const key of TAPE_ACTIONS) {
      const value = raw.probabilities[key] ?? 0;
      if (typeof value !== "number" || !Number.isFinite(value) || value < 0) return holdOnly(model, latency, "malformed");
      weights[key] = value;
      total += value;
    }
    if (!Number.isFinite(total) || !(total > 0) || !(weights[action] > 0)) return holdOnly(model, latency, "malformed");
    probabilities = { buy: weights.buy / total, sell: weights.sell / total, hold: weights.hold / total };
    if (!TAPE_ACTIONS.every((key) => Number.isFinite(probabilities[key])) || !(probabilities[action] > 0)) return holdOnly(model, latency, "malformed");
  }

